/**
 * Detect the delimiter used in a CSV header line.
 * Counts semicolons vs commas; whichever is more frequent wins.
 * Ties default to semicolon (Kruitbosch convention).
 * Empty/single-field lines default to comma.
 */
export function detectDelimiter(line: string): ',' | ';' {
  if (!line || !line.includes(';') && !line.includes(',')) return ','

  const semiCount = (line.match(/;/g) || []).length
  const commaCount = (line.match(/,/g) || []).length

  // Semicolon wins when tied or more frequent; comma only when strictly more
  return semiCount >= commaCount ? ';' : ','
}

